      "rank": 1,
      "ballot_id": "B043",
      "proposed_laureates": [
        "Hidetoshi Katori",
        "Jun Ye"
      ],
      "assessment": {
        "nobel_worthiness": "Optical lattice clocks turned optical transitions into exceptionally precise, stable frequency standards. Their precision enables stringent tests of fundamental physics and practical advances in timekeeping.",
        "attribution": "Katori and Ye independently established leading approaches to trapping and interrogating atoms in optical lattices; both are central to the field's development.",
        "maturity": "The clocks have been repeatedly demonstrated and refined over decades, with accuracy and reproducibility sufficient for major metrological impact.",
        "uncertainties": [
          "The eventual redefinition of the second is still under discussion, though the scientific contribution is already substantial."
        ]
      }
    },
    {
      "rank": 2,
      "ballot_id": "B047",
      "proposed_laureates": [
        "Carlton M. Caves",
        "H. Jeff Kimble",
        "Nergis Mavalvala"
      ],
      "assessment": {
        "nobel_worthiness": "Squeezed light established a practical route to surpassing quantum noise limits in precision measurement, with direct impact on gravitational-wave detection and broader quantum metrology.",
        "attribution": "Caves provided key theoretical foundations; Kimble helped develop and demonstrate squeezed-light techniques; Mavalvala was central to bringing them into gravitational-wave observatories.",
        "maturity": "The effect is well established in the laboratory and is now used to improve the sensitivity of operating gravitational-wave detectors.",
        "uncertainties": [
          "The field includes important contributions from more researchers than a Nobel-sized group can recognize."
        ]
      }
    },
    {
      "rank": 3,
      "ballot_id": "B053",
      "proposed_laureates": [
        "Christian J. Bordé",
        "David E. Pritchard",
        "Mark A. Kasevich"
      ],
      "assessment": {
        "nobel_worthiness": "Atom interferometry made matter-wave phase measurements a powerful tool for precision tests of fundamental physics and measurements of acceleration, rotation, and gravity.",
        "attribution": "Bordé and Pritchard helped establish atom-interferometric methods, while Kasevich demonstrated influential high-precision implementations and applications.",
        "maturity": "The technique has been validated across many experiments and has a sustained record of improving measurement sensitivity.",
        "uncertainties": [
          "Its broad development makes it difficult to draw a sharp boundary around the founding contributions."
        ]
      }
    },
    {
      "rank": 4,
      "ballot_id": "B007",
      "proposed_laureates": [
        "Harald Rose",
        "Knut Urban",
        "Maximilian Haider"
      ],
      "assessment": {
        "nobel_worthiness": "Spherical-aberration correction overcame a fundamental practical limit in electron microscopy, enabling atomic-scale structural studies with much greater resolution and interpretability.",
        "attribution": "Rose supplied essential optical theory; Haider and Urban were instrumental in realizing and validating correctors in working microscopes.",
        "maturity": "The correction has been demonstrated, independently validated, and incorporated into widely used instruments.",
        "uncertainties": [
          "The division between theoretical invention, instrument realization, and later development needs careful historical assessment."
        ]
      }
    },
    {
      "rank": 5,
      "ballot_id": "B002",
      "proposed_laureates": [
        "Alexei Kitaev",
        "Andrew M. Steane",
        "Peter W. Shor"
      ],
      "assessment": {
        "nobel_worthiness": "Quantum error correction showed how fragile quantum information could be protected in principle, while fault-tolerant codes provide a foundation for scalable quantum computation.",
        "attribution": "Shor and Steane introduced landmark quantum codes; Kitaev developed influential topological approaches that connected error correction with robust phases of matter.",
        "maturity": "The theory is firmly established, and experiments increasingly demonstrate encoded operations and error suppression, although large-scale fault tolerance remains a goal.",
        "uncertainties": [
          "The ultimate practical reach of fault-tolerant quantum computing is not yet settled.",
          "The field's many contributors complicate a compact attribution."
        ]
      }
    },
    {
      "rank": 6,
      "ballot_id": "B014",
      "proposed_laureates": [
        "Kenneth J. Schafer",
        "Maciej Lewenstein",
        "Paul B. Corkum"
      ],
      "assessment": {
        "nobel_worthiness": "The recollision picture explained how intense laser fields can drive high-harmonic emission and opened a route to attosecond pulses and observation of ultrafast electronic motion.",
        "attribution": "Corkum and Schafer developed influential recollision models, with Lewenstein making a major theoretical contribution to the quantitative description of high-harmonic generation.",
        "maturity": "The mechanism has been experimentally confirmed and underpins a mature field of attosecond science.",
        "uncertainties": [
          "Several experimental and theoretical groups contributed to the field's development beyond the named proponents."
        ]
      }
    },
    {
      "rank": 7,
      "ballot_id": "B008",
      "proposed_laureates": [
        "Heino Falcke",
        "J. Anton Zensus",
        "Sheperd S. Doeleman"
      ],
      "assessment": {
        "nobel_worthiness": "The Event Horizon Telescope produced resolved images of black-hole-scale emission, a striking test of strong-field gravity and a major advance in very-long-baseline imaging.",
        "attribution": "Falcke helped articulate the imaging target and its scientific case; Zensus contributed leadership in radio astronomy and VLBI; Doeleman led key efforts to make the Earth-sized array and observations possible.",
        "maturity": "The imaging results have been published and followed by further observations and analysis, though interpretation depends on complex calibration and modeling.",
        "uncertainties": [
          "The achievement is highly collaborative, making individual attribution difficult.",
          "The image traces emission around the black hole rather than directly resolving the event horizon."
        ]
      }
    },
    {
      "rank": 8,
      "ballot_id": "B059",
      "proposed_laureates": [
        "Artur K. Ekert",
        "Charles H. Bennett",
        "Gilles Brassard"
      ],
      "assessment": {
        "nobel_worthiness": "Quantum key distribution connected quantum measurement principles to secure communication and established a foundational direction in quantum information science.",
        "attribution": "Bennett and Brassard introduced BB84; Ekert independently developed a protocol grounded in entanglement and Bell tests. The named contributions are distinct and complementary.",
        "maturity": "The protocols are well established experimentally, and quantum communication systems have been demonstrated in varied settings.",
        "uncertainties": [
          "Practical security depends on implementation details, and the broader field includes substantial later contributions."
        ]
      }
    }
  ]
